namespace Payments;

public sealed class SettlementBatchProcessor
{
    public SettlementResult Process(string merchantId, IEnumerable<PaymentItem> items, string settlementCurrency,
        decimal percentageFee, decimal fixedFee, decimal submissionLimit, ISettlementGateway gateway)
    {
        var lines = new List<SettlementLine>();
        var accepted = new List<(string Reference, decimal Net)>();
        var seen = new HashSet<string>(StringComparer.Ordinal);

        EvaluateItems(items, settlementCurrency, percentageFee, fixedFee, submissionLimit, seen, lines, accepted);
        return CompleteSettlement(merchantId, settlementCurrency, gateway, lines, accepted);
    }

    private static void EvaluateItems(IEnumerable<PaymentItem> items, string settlementCurrency,
        decimal percentageFee, decimal fixedFee, decimal submissionLimit, HashSet<string> seen,
        List<SettlementLine> lines, List<(string Reference, decimal Net)> accepted)
    {
        foreach (var item in items)
        {
            var evaluation = EvaluateItem(item, settlementCurrency, percentageFee, fixedFee,
                submissionLimit, seen, accepted);

            if (evaluation.RejectionStatus is not null)
            {
                lines.Add(new SettlementLine(item.Reference, 0m, evaluation.RejectionStatus));
                continue;
            }

            accepted.Add((item.Reference, evaluation.Net));
        }
    }

    private static (decimal Net, string? RejectionStatus) EvaluateItem(PaymentItem item,
        string settlementCurrency, decimal percentageFee, decimal fixedFee, decimal submissionLimit,
        HashSet<string> seen, List<(string Reference, decimal Net)> accepted)
    {
        if (string.IsNullOrWhiteSpace(item.Reference))
            return (0m, "invalid-reference");
        if (!seen.Add(item.Reference))
            return (0m, "duplicate");
        if (!string.Equals(item.Currency, settlementCurrency, StringComparison.OrdinalIgnoreCase))
            return (0m, "currency-mismatch");
        if (item.GrossAmount <= 0m)
            return (0m, "invalid-amount");
        if (item.Refunded)
            return (0m, "refunded");
        if (item.Held)
            return (0m, "held");

        var fee = decimal.Round(item.GrossAmount * percentageFee + fixedFee, 2);
        var net = decimal.Round(item.GrossAmount - fee, 2);
        if (net <= 0m)
            return (0m, "fee-exceeds-amount");
        if (accepted.Sum(entry => entry.Net) + net > submissionLimit)
            return (0m, "batch-limit");

        return (net, null);
    }

    private static SettlementResult CompleteSettlement(string merchantId, string settlementCurrency,
        ISettlementGateway gateway, List<SettlementLine> lines,
        List<(string Reference, decimal Net)> accepted)
    {
        if (accepted.Count == 0)
            return new SettlementResult(lines, 0m, "empty");
        if (string.IsNullOrWhiteSpace(merchantId))
            return RejectedResult(lines, accepted, "invalid-merchant");

        var total = accepted.Sum(entry => entry.Net);
        var references = accepted.Select(entry => entry.Reference).ToArray();
        var gatewayResult = gateway.Submit(merchantId, settlementCurrency, total, references);
        if (!gatewayResult.Accepted)
            return RejectedResult(lines, accepted, $"gateway-{gatewayResult.Code}");

        lines.AddRange(accepted.Select(entry => new SettlementLine(entry.Reference, entry.Net, "submitted")));
        var status = lines.Any(line => line.Status != "submitted") ? "partial" : "submitted";
        return new SettlementResult(lines, total, status);
    }

    private static SettlementResult RejectedResult(List<SettlementLine> lines,
        List<(string Reference, decimal Net)> accepted, string rejectionStatus)
    {
        var rejectedLines = accepted.Select(entry => new SettlementLine(entry.Reference, 0m, rejectionStatus));
        return new SettlementResult([.. lines, .. rejectedLines], 0m, "rejected");
    }
}
